(* 7701(b)(3)(C): closer-connection exception (B) not apply if adjustment-of-status or LPR steps pending *)
let is_adjustment_of_status_exception (has_pending_adjustment_of_status_application : bool) : bool =
  has_pending_adjustment_of_status_application

let is_lawful_permanent_resident_steps_exception (took_steps_to_apply_for_lawful_permanent_resident_status : bool) : bool =
  took_steps_to_apply_for_lawful_permanent_resident_status
